from flask import Flask, request, jsonify
from flask_cors import CORS
import os, uuid, math
app = Flask(__name__)
CORS(app)
POSTS=[]; COMMENTS={}; CHATS={}; MESSAGES={}; INTERACTIONS={}; FRIENDS=set(); PAGES=[]; GIFTS=[]; VIEWS={"total":45000,"followers":1250}
PROFILE={"name":"يوسف إبراهيم","city":"عطبرة","bio":"منشئ محتوى من عطبرة ❤️","avatar":"https://i.pravatar.cc/150?u=me","cover":"https://picsum.photos/800/300","phone":"0912345678","birthday":"2000-01-01","gender":"ذكر"}
SETTINGS={"demo":{"two_factor":False,"active_status":True,"app_lock":0,"default_audience":"PUBLIC"}}
def feed_algo(posts):
    out=[]
    for p in posts:
        aff=INTERACTIONS.get(p.get("author_id"),0)*10
        score=p.get("likes_count",0)*2+p.get("comments_count",0)*3+p.get("shares_count",0)*4+aff+10
        pp=dict(p); pp["algo_reason"]=f"لايك {p.get('likes_count',0)}x2 + تعليق {p.get('comments_count',0)}x3 + تفاعلك {aff} = {score}"; out.append(pp)
    return sorted(out, key=lambda x: x.get("likes_count",0)*2+x.get("comments_count",0)*3+INTERACTIONS.get(x.get("author_id"),0)*10, reverse=True)
def suggest_algo():
    return [{"id":str(uuid.uuid4()),"name":n,"city":c,"mutual":m,"reason":f"{m} اصدقاء مشتركين","avatar":f"https://i.pravatar.cc/150?u={n}"} for n,c,m in [("أحمد علي","عطبرة",5),("سارة محمد","الخرطوم",12),("يوسف إبراهيم","عطبرة",8)] if n not in FRIENDS]
def privacy_algo(s):
    score=100; recs=[]
    if not s.get("two_factor"): score-=30; recs.append("فعل المصادقة الثنائية +30%")
    if s.get("default_audience")=="PUBLIC": score-=15; recs.append("خلي منشوراتك للاصدقاء +15%")
    if not s.get("app_lock"): score-=10; recs.append("فعل قفل الشات +10%")
    if s.get("active_status"): score-=5; recs.append("اخفي حالة النشاط +5%")
    return {"score":max(0,score),"status":"ممتاز" if score>=85 else "جيد","fixes":recs}
def monetization_algo():
    views=VIEWS["total"]; followers=VIEWS["followers"]; gifts=sum(g["value"] for g in GIFTS)
    earnings=round(views/1000*2,2); total=round(earnings+gifts,2)
    if followers<100: live={"allowed":False,"reason":f"عندك {followers} متابع - لازم 100 متابع عشان تعمل لايف","level":"ممنوع"}
    elif followers<1000: live={"allowed":True,"reason":f"عندك {followers} متابع - لايف عادي 60 دقيقة","level":"عادي"}
    else: live={"allowed":True,"reason":f"عندك {followers} متابع - لايف + هدايا + ارباح","level":"محترف"}
    return {"followers":followers,"views":views,"earnings":earnings,"gifts":gifts,"total":total,"live":live,"rule":"1000 مشاهدة = 2$ - وردة 0.10$ - اسد 10$"}
def diagnostics():
    tests=[]
    try: feed_algo(POSTS); tests.append({"name":"خوارزمية الفيد","status":"شغال ✅","detail":"رتبت البوستات حسب اللايك + تفاعلك"})
    except Exception as e: tests.append({"name":"خوارزمية الفيد","status":"خربان ❌","detail":str(e)})
    try: suggest_algo(); tests.append({"name":"خوارزمية الاقتراح","status":"شغال ✅","detail":"اقترح حسب الاصدقاء المشتركين"})
    except Exception as e: tests.append({"name":"خوارزمية الاقتراح","status":"خربان ❌","detail":str(e)})
    try: privacy_algo(SETTINGS["demo"]); tests.append({"name":"خوارزمية الخصوصية","status":"شغال ✅","detail":f"نقاطك {privacy_algo(SETTINGS['demo'])['score']}%"})
    except Exception as e: tests.append({"name":"خوارزمية الخصوصية","status":"خربان ❌","detail":str(e)})
    try: monetization_algo(); tests.append({"name":"خوارزمية الارباح","status":"شغال ✅","detail":f"ارباحك {monetization_algo()['total']}$"})
    except Exception as e: tests.append({"name":"خوارزمية الارباح","status":"خربان ❌","detail":str(e)})
    tests.append({"name":"إنشاء صفحة","status":"شغال ✅","detail":f"عندك {len(PAGES)} صفحة"})
    tests.append({"name":"الملف الشخصي","status":"شغال ✅","detail":PROFILE["name"]+" - "+PROFILE["city"]})
    tests.append({"name":"نور شات","status":"شغال ✅","detail":f"{len(CHATS)} محادثة"})
    ok=sum(1 for t in tests if "✅" in t["status"]); return {"tests":tests,"summary":f"{ok}/{len(tests)} خوارزميات شغالة","all_ok":ok==len(tests)}

